<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { api, ApiError, jsonBody } from '../api'
const props=defineProps<{authorities:string[]}>(), emit=defineEmits<{expired:[]}>()
const route=useRoute(),router=useRouter(),admin=computed(()=>props.authorities.includes('ROLE_ADMIN'))
const section=computed(()=>String(route.params.section||'overview'))
const loading=ref(false),error=ref(''),notice=ref('')
const overview=ref<any>({}),users=ref<any>({items:[],page:1,size:20,total:0}),groups=ref<any[]>([]),tasks=ref<any>({items:[],page:1,size:20,total:0}),audit=ref<any>({items:[],page:1,size:20,total:0}),system=ref<any>({})
const selectedGroup=ref<any>(null),selectedTask=ref<any>(null),temporaryPassword=ref('')
const taskMembers=ref<any[]>([]),newAssignee=ref('')
const uq=ref(''),urole=ref(''),uenabled=ref(''),tq=ref(''),tstatus=ref(''),tgroup=ref(''),tassignee=ref(''),tfrom=ref(''),tto=ref(''),toverdue=ref(false),aq=ref(''),aa=ref('')
const newUser=ref({username:'',password:'',displayName:'',role:'MEMBER'}),member=ref({groupId:'',userId:'',position:'',leader:false})
const nav=[['overview','总览'],['users','账号'],['groups','组织'],['tasks','任务'],['audit','审计'],['system','系统状态']]
const roleNames:any={ADMIN:'管理员',MINISTER:'部长',LEADER:'组长',MEMBER:'部员',GUEST:'访客'}
const statusNames:any={TODO:'待处理',IN_PROGRESS:'进行中',REVIEW:'待验收',DONE:'已完成'}
const actionNames:any={LOGIN_FAILED:'登录失败',LOGIN_SUCCEEDED:'登录成功',USER_CREATED:'创建账号',PASSWORD_RESET:'重置密码',PROFILE_UPDATED:'修改资料',GROUP_MEMBER_SET:'设置小组成员',TASK_REASSIGNED:'调整任务负责人'}
function go(key:string){router.push('/admin/'+key)}
function fail(e:unknown){if(e instanceof ApiError&&e.status===401)emit('expired');else error.value=e instanceof Error?e.message:'加载失败'}
async function run(fn:()=>Promise<void>){loading.value=true;error.value='';notice.value='';try{await fn()}catch(e){fail(e)}finally{loading.value=false}}
async function load(){await run(async()=>{
  if(section.value==='overview')overview.value=await api('/admin/overview')
  if(section.value==='users')await loadUsers()
  if(section.value==='groups'){groups.value=await api('/admin/groups');users.value=await api('/admin/users?size=100')}
  if(section.value==='tasks'){groups.value=await api('/admin/groups');users.value=await api('/admin/users?size=100&enabled=true');await loadTasks()}
  if(section.value==='audit')await loadAudit()
  if(section.value==='system')system.value=await api('/admin/system')
})}
async function loadUsers(page=1){const p=new URLSearchParams({page:String(page),size:'20'});if(uq.value)p.set('q',uq.value);if(urole.value)p.set('role',urole.value);if(uenabled.value)p.set('enabled',uenabled.value);users.value=await api('/admin/users?'+p)}
async function loadTasks(page=1){const p=new URLSearchParams({page:String(page),size:'20'});if(tq.value)p.set('q',tq.value);if(tstatus.value)p.set('status',tstatus.value);if(tgroup.value)p.set('groupId',tgroup.value);if(tassignee.value)p.set('assigneeId',tassignee.value);if(tfrom.value)p.set('dueFrom',tfrom.value);if(tto.value)p.set('dueTo',tto.value);if(toverdue.value)p.set('overdue','true');tasks.value=await api('/admin/tasks?'+p)}
async function loadAudit(page=1){const p=new URLSearchParams({page:String(page),size:'20'});if(aq.value)p.set('actor',aq.value);if(aa.value)p.set('action',aa.value);audit.value=await api('/admin/audit?'+p)}
async function createUser(){await run(async()=>{await api('/admin/users',jsonBody('POST',newUser.value));newUser.value={username:'',password:'',displayName:'',role:'MEMBER'};notice.value='账号已创建，首次登录会要求修改密码';await loadUsers()})}
async function editUser(u:any){const displayName=prompt('显示姓名',u.display_name);if(displayName===null)return;await run(async()=>{await api(`/admin/users/${u.id}`,jsonBody('PATCH',{displayName}));notice.value='姓名已更新';await loadUsers(users.value.page)})}
async function changeRole(u:any){const role=prompt('输入角色代码：ADMIN / MINISTER / LEADER / MEMBER / GUEST',u.role);if(!role||role===u.role)return;await run(async()=>{await api(`/admin/users/${u.id}`,jsonBody('PATCH',{role}));notice.value='角色已更新，旧会话已撤销';await loadUsers(users.value.page)})}
async function toggleUser(u:any){if(!confirm(`确认${u.enabled?'停用':'启用'} ${u.display_name}？`))return;await run(async()=>{await api(`/admin/users/${u.id}`,jsonBody('PATCH',{enabled:!u.enabled}));notice.value='账号状态已更新';await loadUsers(users.value.page)})}
async function resetPassword(u:any){if(!confirm(`确认重置 ${u.display_name} 的密码？旧会话会立即失效。`))return;await run(async()=>{const r=await api<{temporaryPassword:string}>(`/admin/users/${u.id}/reset-password`,{method:'POST'});temporaryPassword.value=r.temporaryPassword;notice.value='临时密码只显示这一次，请立即安全交给本人';await loadUsers(users.value.page)})}
async function openGroup(id:number){await run(async()=>{selectedGroup.value=await api(`/admin/groups/${id}`)})}
async function createGroup(){const name=prompt('新小组名称');if(!name)return;await run(async()=>{await api('/groups',jsonBody('POST',{name}));notice.value='小组已创建';groups.value=await api('/admin/groups')})}
async function renameGroup(){const name=prompt('新的小组名称',selectedGroup.value?.name);if(!name||!selectedGroup.value)return;await run(async()=>{await api(`/groups/${selectedGroup.value.id}`,jsonBody('PATCH',{name}));notice.value='小组名称已更新';groups.value=await api('/admin/groups');await openGroup(selectedGroup.value.id)})}
async function removeMember(userId:number){if(!selectedGroup.value||!confirm('确认将该成员移出小组？'))return;await run(async()=>{await api(`/groups/${selectedGroup.value.id}/members/${userId}`,{method:'DELETE'});notice.value='成员已移出小组';await openGroup(selectedGroup.value.id);groups.value=await api('/admin/groups')})}
async function setMember(){await run(async()=>{await api(`/admin/groups/${member.value.groupId}/members/${member.value.userId}`,jsonBody('PUT',{position:member.value.position,leader:member.value.leader}));notice.value='成员关系已保存';groups.value=await api('/admin/groups');await openGroup(Number(member.value.groupId))})}
async function openTask(id:number){await run(async()=>{selectedTask.value=await api(`/admin/tasks/${id}`);const group:any=await api(`/admin/groups/${selectedTask.value.group_id}`);taskMembers.value=group.members;newAssignee.value=String(selectedTask.value.assignee_id)})}
async function reassign(){if(!selectedTask.value||!newAssignee.value)return;await run(async()=>{await api(`/admin/tasks/${selectedTask.value.id}/assignee`,jsonBody('PATCH',{assigneeId:Number(newAssignee.value),version:selectedTask.value.version}));notice.value='任务负责人已更新';await openTask(selectedTask.value.id);await loadTasks(tasks.value.page)})}
async function reviewTask(action:'APPROVE'|'RETURN'){if(!selectedTask.value)return;await run(async()=>{await api(`/tasks/${selectedTask.value.id}`,jsonBody('PATCH',{action,progress:selectedTask.value.progress,version:selectedTask.value.version}));notice.value=action==='APPROVE'?'任务已通过验收':'任务已退回';await openTask(selectedTask.value.id);await loadTasks(tasks.value.page)})}
watch(section,load);onMounted(load)
</script>
<template>
  <div class="admin-grid">
    <nav aria-label="后台导航"><button v-for="item in nav" :key="item[0]" :class="{active:section===item[0]}" @click="go(item[0])">{{item[1]}}</button></nav>
    <div class="admin-content"><p v-if="error" class="error">{{error}}</p><p v-if="notice" class="notice">{{notice}}</p><p v-if="loading" class="muted">正在更新数据…</p>
      <template v-if="section==='overview'">
        <div class="section-title"><div><h2>运行总览</h2><p>部门当前账号、组织和任务概况</p></div><button class="secondary" @click="load">刷新</button></div>
        <div class="metrics"><article><span>账号总数</span><strong>{{overview.accounts?.total??'-'}}</strong><small>启用 {{overview.accounts?.enabled??0}} · 停用 {{overview.accounts?.disabled??0}}</small></article><article><span>小组</span><strong>{{overview.groups?.total??'-'}}</strong><small>未分组 {{overview.groups?.ungrouped??0}} · 无负责人 {{overview.groups?.withoutLeader??0}}</small></article><article><span>进行中任务</span><strong>{{overview.tasks?.active??'-'}}</strong><small>待验收 {{overview.tasks?.review??0}}</small></article><article><span>逾期任务</span><strong>{{overview.tasks?.overdue??'-'}}</strong><small>近 7 日完成 {{overview.tasks?.recentDone??0}}</small></article></div>
        <h3>角色分布</h3><div class="chips"><span v-for="r in overview.roles" :key="r.code">{{r.name}} {{r.count}}</span></div>
      </template>
      <template v-if="section==='users'">
        <div class="section-title"><div><h2>账号管理</h2><p>共 {{users.total}} 个账号</p></div></div>
        <form class="filters" @submit.prevent="loadUsers()"><input v-model="uq" placeholder="姓名或账号"/><select v-model="urole"><option value="">全部角色</option><option v-for="(name,code) in roleNames" :value="code">{{name}}</option></select><select v-model="uenabled"><option value="">全部状态</option><option value="true">启用</option><option value="false">停用</option></select><button>查询</button></form>
        <details open><summary>新建账号</summary><form class="form-grid" @submit.prevent="createUser"><label>账号<input v-model="newUser.username" required minlength="3" maxlength="64"/></label><label>姓名<input v-model="newUser.displayName" required maxlength="100"/></label><label>初始密码<input v-model="newUser.password" type="password" required minlength="12" maxlength="72"/></label><label>角色<select v-model="newUser.role"><option v-for="(name,code) in roleNames" :value="code" :disabled="!admin&&(code==='ADMIN'||code==='MINISTER')">{{name}}</option></select></label><button :disabled="loading">创建</button></form></details>
        <div v-if="temporaryPassword" class="secret"><strong>一次性临时密码</strong><code>{{temporaryPassword}}</code><button class="secondary" @click="temporaryPassword=''">我已保存</button></div>
        <div class="table-wrap"><table><thead><tr><th>姓名 / 账号</th><th>角色</th><th>小组</th><th>最近登录</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="u in users.items" :key="u.id"><td><strong>{{u.display_name}}</strong><small>{{u.username}}</small></td><td>{{roleNames[u.role]||u.role}}</td><td>{{u.group_count}}</td><td>{{u.last_login_at||'从未登录'}}</td><td><span :class="['tag',u.enabled?'ok':'off']">{{u.enabled?'启用':'停用'}}</span><small v-if="u.must_change_password">待改密</small></td><td class="actions"><button class="secondary" @click="editUser(u)">姓名</button><button v-if="admin" class="secondary" @click="changeRole(u)">角色</button><button class="secondary" @click="toggleUser(u)">{{u.enabled?'停用':'启用'}}</button><button v-if="admin" class="danger" @click="resetPassword(u)">重置密码</button></td></tr></tbody></table></div>
        <div class="pager"><button class="secondary" :disabled="users.page<=1" @click="loadUsers(users.page-1)">上一页</button><span>第 {{users.page}} / {{Math.max(1,Math.ceil(users.total/users.size))}} 页</span><button class="secondary" :disabled="users.page*users.size>=users.total" @click="loadUsers(users.page+1)">下一页</button></div>
      </template>
      <template v-if="section==='groups'">
        <div class="section-title"><div><h2>组织与小组</h2><p>成员关系、职务和负责人</p></div><button @click="createGroup">新建小组</button></div><div class="cards"><button v-for="g in groups" :key="g.id" class="group-card" @click="openGroup(g.id)"><strong>{{g.name}}</strong><span>{{g.member_count}} 名成员 · {{g.leader_count}} 名负责人</span><small>{{g.open_task_count}} 项未完成任务</small></button></div>
        <section v-if="selectedGroup" class="drawer"><div class="section-title"><h3>{{selectedGroup.name}}</h3><div class="actions"><button class="secondary" @click="renameGroup">重命名</button><button class="secondary" @click="selectedGroup=null">关闭</button></div></div><p v-if="!selectedGroup.members.length" class="muted">暂无成员</p><p v-for="m in selectedGroup.members" :key="m.id"><strong>{{m.display_name}}</strong> · {{m.position_name||'未设职务'}} · {{roleNames[m.role]}} <span v-if="m.is_leader" class="tag ok">负责人</span> <button class="secondary mini" @click="removeMember(m.id)">移出</button></p></section>
        <details><summary>添加或更新成员关系</summary><form class="form-grid" @submit.prevent="setMember"><label>小组<select v-model="member.groupId" required><option value="" disabled>选择小组</option><option v-for="g in groups" :value="g.id">{{g.name}}</option></select></label><label>成员<select v-model="member.userId" required><option value="" disabled>选择成员</option><option v-for="u in users.items" :value="u.id">{{u.display_name}}（{{u.username}}）</option></select></label><label>组内职务<input v-model="member.position" maxlength="100"/></label><label class="check"><input v-model="member.leader" type="checkbox"/> 设为负责人</label><button>保存</button></form></details>
      </template>
      <template v-if="section==='tasks'">
        <div class="section-title"><div><h2>任务监管</h2><p>共 {{tasks.total}} 项任务</p></div></div><form class="filters task-filters" @submit.prevent="loadTasks()"><input v-model="tq" placeholder="任务标题或说明"/><select v-model="tgroup"><option value="">全部小组</option><option v-for="g in groups" :value="g.id">{{g.name}}</option></select><select v-model="tassignee"><option value="">全部负责人</option><option v-for="u in users.items" :value="u.id">{{u.display_name}}</option></select><select v-model="tstatus"><option value="">全部状态</option><option v-for="(name,code) in statusNames" :value="code">{{name}}</option></select><label>截止日期从<input v-model="tfrom" type="date"/></label><label>截止日期至<input v-model="tto" type="date"/></label><label class="check"><input v-model="toverdue" type="checkbox"/> 只看逾期</label><button>查询</button></form>
        <div class="table-wrap"><table><thead><tr><th>任务</th><th>小组</th><th>负责人</th><th>状态</th><th>进度</th><th>截止</th></tr></thead><tbody><tr v-for="t in tasks.items" :key="t.id" class="clickable" @click="openTask(t.id)"><td>{{t.title}}</td><td>{{t.group_name}}</td><td>{{t.assignee_name}}</td><td>{{statusNames[t.status]}}</td><td>{{t.progress}}%</td><td>{{t.due_date||'未设置'}}</td></tr></tbody></table></div><div class="pager"><button class="secondary" :disabled="tasks.page<=1" @click="loadTasks(tasks.page-1)">上一页</button><span>第 {{tasks.page}} 页</span><button class="secondary" :disabled="tasks.page*tasks.size>=tasks.total" @click="loadTasks(tasks.page+1)">下一页</button></div>
        <section v-if="selectedTask" class="drawer"><div class="section-title"><div><h3>{{selectedTask.title}}</h3><p>{{selectedTask.description}}</p></div><button class="secondary" @click="selectedTask=null">关闭</button></div><p>负责人：{{selectedTask.assignee_name}} · 创建人：{{selectedTask.creator_name}}</p><form class="inline-form" @submit.prevent="reassign"><select v-model="newAssignee"><option v-for="m in taskMembers" :value="m.id">{{m.display_name}}</option></select><button>调整负责人</button><button v-if="selectedTask.status==='REVIEW'" type="button" @click="reviewTask('APPROVE')">通过验收</button><button v-if="selectedTask.status==='REVIEW'" type="button" class="danger" @click="reviewTask('RETURN')">退回修改</button></form><h4>流转记录</h4><p v-if="!selectedTask.events.length" class="muted">旧任务暂无流转记录</p><p v-for="e in selectedTask.events" :key="e.id">{{e.created_at}} · {{e.actor}} · {{e.action}} · {{statusNames[e.to_status]}} {{e.progress}}%</p><h4>评论与附件</h4><p>{{selectedTask.comments.length}} 条评论 · {{selectedTask.attachments.length}} 个附件</p></section>
      </template>
      <template v-if="section==='audit'"><div class="section-title"><div><h2>操作审计</h2><p>共 {{audit.total}} 条记录</p></div></div><form class="filters" @submit.prevent="loadAudit()"><input v-model="aq" placeholder="操作人"/><input v-model="aa" placeholder="操作代码"/><button>查询</button></form><div class="table-wrap"><table><thead><tr><th>时间</th><th>操作人</th><th>操作</th><th>对象</th></tr></thead><tbody><tr v-for="a in audit.items" :key="a.id"><td>{{a.created_at}}</td><td>{{a.actor}}</td><td><strong>{{actionNames[a.action]||a.action}}</strong><small>{{a.action}}</small></td><td>{{a.target}}</td></tr></tbody></table></div><div class="pager"><button class="secondary" :disabled="audit.page<=1" @click="loadAudit(audit.page-1)">上一页</button><span>第 {{audit.page}} 页</span><button class="secondary" :disabled="audit.page*audit.size>=audit.total" @click="loadAudit(audit.page+1)">下一页</button></div></template>
      <template v-if="section==='system'"><div class="section-title"><div><h2>系统状态</h2><p>只读检查，不执行服务器操作</p></div><button class="secondary" @click="load">重新检查</button></div><div class="metrics"><article><span>应用</span><strong>{{system.application}}</strong></article><article><span>数据库</span><strong>{{system.database}}</strong></article><article><span>附件存储</span><strong>{{system.storage}}</strong></article><article><span>版本</span><strong class="version">{{system.version}}</strong></article></div></template>
    </div>
  </div>
</template>
<style scoped>
.admin-grid{display:grid;grid-template-columns:180px 1fr;gap:28px;border-top:1px solid #e2ebe7;padding-top:24px}nav{display:flex;flex-direction:column;gap:6px}nav button{background:transparent;color:#47655e;text-align:left}nav button.active{background:#176c58;color:#fff}.admin-content{min-width:0}.section-title{display:flex;align-items:start;justify-content:space-between;gap:16px;margin-bottom:18px}.section-title h2,.section-title h3{margin:0}.section-title p{margin:6px 0;color:#71817d}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.metrics article{border:1px solid #dfe9e5;border-radius:12px;padding:20px;display:flex;flex-direction:column;gap:8px}.metrics strong{font-size:30px}.metrics small,td small{display:block;color:#71817d;margin-top:4px}.chips{display:flex;gap:10px;flex-wrap:wrap}.chips span,.tag{background:#edf4f1;border-radius:20px;padding:6px 10px}.tag.off{background:#f2f2f2;color:#777}.filters,.form-grid{display:grid;grid-template-columns:repeat(4,minmax(120px,1fr));gap:12px;align-items:end;margin:16px 0}.filters input,.filters select{margin:0}.filters button{height:46px}.form-grid label{margin:0}.form-grid button{height:46px}.table-wrap{overflow:auto;border:1px solid #dfe9e5;border-radius:12px;margin-top:16px}table{border-collapse:collapse;width:100%;min-width:780px}th,td{padding:13px;text-align:left;border-bottom:1px solid #edf2f0;vertical-align:top}.actions,.inline-form{display:flex;gap:6px;flex-wrap:wrap}.actions button,.mini{padding:7px 10px;font-size:12px}.inline-form select{max-width:260px}.inline-form button{white-space:nowrap}.danger{background:#a13f3f}.notice{background:#e9f7ef;color:#19633f;padding:12px;border-radius:8px}.secret{margin:16px 0;padding:16px;border:1px solid #d4b35d;background:#fff9e8;border-radius:10px;display:flex;gap:14px;align-items:center;flex-wrap:wrap}.secret code{font-size:17px}.pager{display:flex;justify-content:center;align-items:center;gap:14px;margin:18px}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.group-card{text-align:left;background:#f5faf8;color:#183b36;border:1px solid #dfe9e5;display:flex;flex-direction:column;gap:8px}.drawer{margin-top:18px;border:1px solid #b8d3ca;border-radius:12px;padding:20px;background:#fbfefd}.check{display:flex;align-items:center;gap:8px}.check input{width:auto}.clickable{cursor:pointer}.clickable:hover{background:#f5faf8}.version{font-size:16px!important;overflow-wrap:anywhere}@media(max-width:850px){.admin-grid{grid-template-columns:1fr}nav{flex-direction:row;overflow:auto}.metrics,.cards{grid-template-columns:repeat(2,1fr)}.filters,.form-grid{grid-template-columns:1fr 1fr}}@media(max-width:520px){.metrics,.cards,.filters,.form-grid{grid-template-columns:1fr}}
</style>
